public BiomeChecker(ConfigHandler.BiomeConfig biomeConfig) {
    comboList = new HashSet<>();
    for (String biomeComboString : biomeConfig.biomeTags.get()) {
        BiomeCombo biomeCombo = new BiomeCombo(biomeComboString);
        comboList.add(biomeCombo);
    }
    whitelist = new HashSet<>();
    for (String biomeString : biomeConfig.biomeWhitelist.get()) {
        whitelist.add(ResourceLocation.tryParse(biomeString));
    }
    blacklist = new HashSet<>();
    for (String biomeString : biomeConfig.biomeBlacklist.get()) {
        blacklist.add(ResourceLocation.tryParse(biomeString));
    }
}

public boolean isBiomeInConfig(Holder<Biome> biome) {
    for (ResourceLocation biomeName : whitelist) {
        TagKey<Biome> tagKey = TagKey.create(Registries.BIOME, biomeName);
        if (biome.is(tagKey)) return true;
        if (biome.is(biomeName)) return true;
    }
    for (ResourceLocation biomeName : blacklist) {
        TagKey<Biome> tagKey = TagKey.create(Registries.BIOME, biomeName);
        if (biome.is(tagKey)) return false;
        if (biome.is(biomeName)) return false;
    }

    for (BiomeCombo biomeCombo : comboList) {
        if (biomeCombo.acceptsBiome(biome)) return true;
    }
    return false;
}

private BiomeCombo(String biomeComboString) {
    String[] typeStrings = biomeComboString.replace(" ", "").split(",");
    neededTags = new ResourceLocation[typeStrings.length];
    inverted = new boolean[typeStrings.length];
    for (int i = 0; i < typeStrings.length; i++) {
        if (typeStrings[i].length() == 0) {
            continue;
        }
        inverted[i] = typeStrings[i].charAt(0) == '!';
        String name = typeStrings[i].replace("!", "");
        neededTags[i] = ResourceLocation.tryParse(name);
    }
}

private boolean acceptsBiome(Holder<Biome> biome) {
    for (int i = 0; i < neededTags.length; i++) {
        ResourceLocation neededBiomeName = neededTags[i];
        if (neededBiomeName == null) continue;
        TagKey<Biome> neededBiomeTag = TagKey.create(Registries.BIOME, neededBiomeName);
        boolean failIfMatches = inverted[i];
        if (failIfMatches) {
            if (biome.is(neededBiomeTag) || biome.is(neededBiomeName)) {
                return false;
            }
        }
        else {
            if (!(biome.is(neededBiomeTag) || biome.is(neededBiomeName))) {
                return false;
            }
        }
    }
    return true;
}

GenerationConfig(final ModConfigSpec.Builder builder, int generationDistance, int generationSeparation, BiomeConfig biomeConfig, float heightMin, float heightMax, List<String> avoidStructures) {
    builder.comment("Controls for spawning structure/mob with world generation");
    builder.push("generation_config");
    this.generationDistance = builder.comment("Smaller number causes more generation, -1 to disable generation", "Maximum number of chunks between placements of this mob/structure.", "NO LONGER USED! USE DATAPACK INSTEAD")
            .translation(LANG_PREFIX + "generation_distance")
            .defineInRange("generation_distance", generationDistance, -1, Integer.MAX_VALUE);
    this.generationSeparation = builder.comment("Smaller number causes more generation, -1 to disable generation", "Minimum number of chunks between placements of this mob/structure.", "NO LONGER USED! USE DATAPACK INSTEAD")
            .translation(LANG_PREFIX + "generation_separation")
            .defineInRange("generation_separation", generationSeparation, -1, Integer.MAX_VALUE);
    this.biomeConfig = biomeConfig;
    this.heightMax = builder.comment("Maximum height for generation placement. -65 to ignore")
            .translation(LANG_PREFIX + "height_max")
            .defineInRange("height_max", heightMax, -65, 256);
    this.heightMin = builder.comment("Minimum height for generation placement. -65 to ignore")
            .translation(LANG_PREFIX + "height_min")
            .defineInRange("height_min", heightMin, -65, 256);
    this.avoidStructures = builder.comment("Names of structures this mob/structure will avoid when generating.", "NO LONGER USED! USE DATAPACK INSTEAD")
            .translation(LANG_PREFIX + "avoid_structures")
            .defineList("avoid_structures", avoidStructures, STRING_PREDICATE);
    builder.pop();
}

